import{_ as t,o as r,c as d,a2 as a}from"./chunks/framework.z3u3TMv0.js";const u=JSON.parse('{"title":"FreeLLM directory","description":"awesome-freellm-apis / freellm.net free LLM API index — provider directory, Base URLs, MiniTavern fill tips, and links to dedicated handbook pages.","frontmatter":{"title":"FreeLLM directory","description":"awesome-freellm-apis / freellm.net free LLM API index — provider directory, Base URLs, MiniTavern fill tips, and links to dedicated handbook pages.","head":[["meta",{"name":"keywords","content":"tavern,AI tavern,MiniTavern,AI companion,AI friend,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobile,Silly Tavern Android,Silly Tavern iOS,AI roleplay,character card,AI chat,mobile AI,offline AI,AI story,local LLM,Ollama,LM Studio,lorebook,regex,BYOK,user guide,docs,AI chat client"}],["meta",{"property":"og:title","content":"FreeLLM directory · MiniTavern Docs"}],["meta",{"property":"og:description","content":"awesome-freellm-apis / freellm.net free LLM API index — provider directory, Base URLs, MiniTavern fill tips, and links to dedicated handbook pages."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/en/free-cloud/freellm"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/en/free-cloud/freellm"}]]},"headers":[],"relativePath":"en/free-cloud/freellm.md","filePath":"en/free-cloud/freellm.md","lastUpdated":1787224147000}'),o={name:"en/free-cloud/freellm.md"};function n(l,e,i,s,p,c){return r(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="freellm-directory" tabindex="-1">FreeLLM directory <a class="header-anchor" href="#freellm-directory" aria-label="Permalink to &quot;FreeLLM directory&quot;">​</a></h1><p>A community <strong>free LLM API directory</strong>: <a href="https://github.com/open-free-llm-api/awesome-freellm-apis" target="_blank" rel="noreferrer">awesome-freellm-apis</a> (data refreshes daily from <a href="https://freellm.net" target="_blank" rel="noreferrer">freellm.net</a>). Dozens of providers, hundreds of free models, with notes on credit cards, phone verification, Base URL, and Key links.</p><p>This page is a <strong>MiniTavern user summary</strong>: how to pick a vendor from the directory, and how it maps to dedicated pages and the overview. <strong>Model IDs, rate limits, and whether something is still free follow freellm.net / each vendor console</strong> (the repo README notes the last update date).</p><h2 id="sites-and-entry-points" tabindex="-1">Sites and entry points <a class="header-anchor" href="#sites-and-entry-points" aria-label="Permalink to &quot;Sites and entry points&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Resource</th><th>URL</th></tr></thead><tbody><tr><td>GitHub repo</td><td><a href="https://github.com/open-free-llm-api/awesome-freellm-apis" target="_blank" rel="noreferrer">open-free-llm-api/awesome-freellm-apis</a></td></tr><tr><td>Chinese README</td><td><a href="https://github.com/open-free-llm-api/awesome-freellm-apis/blob/main/README.zh-CN.md" target="_blank" rel="noreferrer">README.zh-CN.md</a></td></tr><tr><td>Online site</td><td><a href="https://freellm.net" target="_blank" rel="noreferrer">freellm.net</a> (browse · Playground · config generator)</td></tr><tr><td>API Key directory</td><td><a href="https://freellm.net/free-llm-api-keys/" target="_blank" rel="noreferrer">freellm.net/free-llm-api-keys</a></td></tr><tr><td>Model compare</td><td><a href="https://freellm.net/compare/" target="_blank" rel="noreferrer">freellm.net/compare</a></td></tr></tbody></table><h2 id="how-to-use-with-minitavern" tabindex="-1">How to use (with MiniTavern) <a class="header-anchor" href="#how-to-use-with-minitavern" aria-label="Permalink to &quot;How to use (with MiniTavern)&quot;">​</a></h2><ol><li>On <a href="https://freellm.net" target="_blank" rel="noreferrer">freellm.net</a> or the repo “provider directory”, pick a vendor: <strong>prefer no credit card</strong> (e.g. Groq, Gemini, Zhipu Flash).</li><li>Tap the provider’s <strong>Get Key</strong>, register, and copy the API Key.</li><li>Note <strong>Base URL</strong> and <strong>Model ID</strong> (repo Quick Reference / Best Models tables).</li><li>Open MiniTavern: <strong>Settings → Models → Model link → New</strong><ul><li>If this handbook already has a dedicated page / App preset (table below) → follow that page.</li><li>Otherwise pick <strong>Custom (OpenAI)</strong>, paste Base URL + Key + model ID → <strong>Test</strong>.</li></ul></li></ol><p>General steps: <a href="/ultra_guides/en/manual/model-link">Model link</a>. For roleplay, prefer <strong>chat-oriented</strong> text models; coding Agent models may not suit long stories.</p><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td>Inclusion criteria (official)</td><td>Clear free tier (not only short trials), publicly reachable; trial credits must be labeled</td></tr><tr><td>Freshness</td><td>Auto-updated daily; limits and lists change</td></tr><tr><td>vs this handbook</td><td>Overview and dedicated pages cover “how to fill the App”; this page + freellm.net cover “what else you can try”</td></tr></tbody></table><h2 id="dedicated-pages-in-this-handbook-read-first" tabindex="-1">Dedicated pages in this handbook (read first) <a class="header-anchor" href="#dedicated-pages-in-this-handbook-read-first" aria-label="Permalink to &quot;Dedicated pages in this handbook (read first)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Provider</th><th>Handbook</th><th>App platform</th></tr></thead><tbody><tr><td>Agnes AI</td><td><a href="/ultra_guides/en/free-cloud/agnes-ai">Agnes AI</a></td><td>Custom (OpenAI) / Images</td></tr><tr><td>OpenCode Zen</td><td><a href="/ultra_guides/en/free-cloud/opencode-zen">OpenCode Zen</a></td><td>Custom (OpenAI)</td></tr><tr><td>AIHubMix</td><td><a href="/ultra_guides/en/free-cloud/aihubmix">AIHubMix</a></td><td>Custom (OpenAI) / Images</td></tr><tr><td>OpenRouter</td><td><a href="/ultra_guides/en/free-cloud/openrouter">OpenRouter</a></td><td>OpenRouter</td></tr><tr><td>Zhipu / SiliconFlow / Bailian / DeepSeek / Gemini / Groq, etc.</td><td><a href="/ultra_guides/en/free-cloud/">Free cloud overview</a></td><td>See each overview section</td></tr></tbody></table><h2 id="provider-directory-permanent-free-tiers-·-summary" tabindex="-1">Provider directory (permanent free tiers · summary) <a class="header-anchor" href="#provider-directory-permanent-free-tiers-·-summary" aria-label="Permalink to &quot;Provider directory (permanent free tiers · summary)&quot;">​</a></h2><p>Excerpt from the repo “Permanent Free Tiers” (~2026-08-20). <strong>Free model counts change</strong>; full table: <a href="https://github.com/open-free-llm-api/awesome-freellm-apis" target="_blank" rel="noreferrer">GitHub</a> / <a href="https://freellm.net" target="_blank" rel="noreferrer">freellm.net</a>.</p><table tabindex="0"><thead><tr><th>Provider</th><th>~Free models</th><th>Card etc.</th><th>Capabilities</th><th>Key</th></tr></thead><tbody><tr><td>NVIDIA NIM</td><td>125</td><td>Phone verification</td><td>Text / image / video / vision, etc.</td><td><a href="https://build.nvidia.com/settings/api-keys" target="_blank" rel="noreferrer">build.nvidia.com</a></td></tr><tr><td>ModelScope</td><td>56</td><td>Sign-up</td><td>Text / image / video / vision</td><td><a href="https://modelscope.cn/my/myaccesstoken" target="_blank" rel="noreferrer">modelscope.cn</a></td></tr><tr><td>Cloudflare Workers AI</td><td>40</td><td>No</td><td>Text / image / code, etc.</td><td><a href="https://dash.cloudflare.com/profile/api-tokens" target="_blank" rel="noreferrer">dash.cloudflare.com</a></td></tr><tr><td>Google Gemini</td><td>17</td><td>No</td><td>Text / multimodal</td><td><a href="https://aistudio.google.com/app/apikey" target="_blank" rel="noreferrer">aistudio.google.com</a></td></tr><tr><td>GitHub Models</td><td>16</td><td>No</td><td>Text, etc.</td><td><a href="https://github.com/marketplace/models" target="_blank" rel="noreferrer">GitHub Models</a></td></tr><tr><td>LLM7.io</td><td>16</td><td>No</td><td>Text / multimodal</td><td><a href="https://token.llm7.io" target="_blank" rel="noreferrer">token.llm7.io</a></td></tr><tr><td>OVHcloud AI Endpoints</td><td>14</td><td>Sign-up</td><td>Text, etc.</td><td><a href="https://www.ovhcloud.com/en/public-cloud/ai-endpoints/catalog/" target="_blank" rel="noreferrer">ovhcloud.com</a></td></tr><tr><td>Ollama Cloud</td><td>13</td><td>Sign-up</td><td>Text / vision, etc.</td><td><a href="https://ollama.com/settings/keys" target="_blank" rel="noreferrer">ollama.com/settings/keys</a></td></tr><tr><td>Groq</td><td>12</td><td>No</td><td>Text</td><td><a href="https://console.groq.com/keys" target="_blank" rel="noreferrer">console.groq.com/keys</a></td></tr><tr><td>Mistral AI</td><td>12</td><td>No</td><td>Text</td><td><a href="https://console.mistral.ai/api-keys" target="_blank" rel="noreferrer">console.mistral.ai</a></td></tr><tr><td>Cohere</td><td>12</td><td>No</td><td>Text</td><td><a href="https://dashboard.cohere.com/api-keys" target="_blank" rel="noreferrer">dashboard.cohere.com</a></td></tr><tr><td>Kilo Code</td><td>12</td><td>No</td><td>Text, etc.</td><td><a href="https://kilo.ai" target="_blank" rel="noreferrer">kilo.ai</a></td></tr><tr><td>OpenCode Zen</td><td>11</td><td>Sign-up</td><td>See <a href="/ultra_guides/en/free-cloud/opencode-zen">dedicated page</a></td><td><a href="https://opencode.ai/auth" target="_blank" rel="noreferrer">opencode.ai/auth</a></td></tr><tr><td>Cerebras</td><td>8</td><td>No</td><td>Text</td><td><a href="https://cloud.cerebras.ai/" target="_blank" rel="noreferrer">cloud.cerebras.ai</a></td></tr><tr><td>Aion Labs</td><td>7</td><td>Sign-up</td><td>Text (incl. RP-oriented)</td><td><a href="https://www.aionlabs.ai" target="_blank" rel="noreferrer">aionlabs.ai</a></td></tr><tr><td>Hugging Face</td><td>7</td><td>No</td><td>Text / code</td><td><a href="https://huggingface.co/settings/tokens" target="_blank" rel="noreferrer">huggingface.co/settings/tokens</a></td></tr><tr><td>Agnes AI</td><td>5</td><td>Sign-up</td><td>See <a href="/ultra_guides/en/free-cloud/agnes-ai">dedicated page</a></td><td><a href="https://platform.agnes-ai.com/settings/apiKeys" target="_blank" rel="noreferrer">platform.agnes-ai.com</a></td></tr><tr><td>Alibaba Cloud Bailian (intl, etc.)</td><td>5</td><td>Sign-up</td><td>See overview <a href="/ultra_guides/en/free-cloud/#qwen-alibaba-cloud-bailian">Qwen</a></td><td><a href="https://bailian.console.aliyun.com/" target="_blank" rel="noreferrer">Bailian console</a></td></tr><tr><td>Zhipu Z AI</td><td>4</td><td>No</td><td>See overview <a href="/ultra_guides/en/free-cloud/#zhipu-ai-glm">Zhipu</a></td><td><a href="https://open.bigmodel.cn/usercenter/apikeys" target="_blank" rel="noreferrer">open.bigmodel.cn</a></td></tr><tr><td>SambaNova</td><td>4</td><td>Sign-up</td><td>Text</td><td><a href="https://cloud.sambanova.ai/apis" target="_blank" rel="noreferrer">cloud.sambanova.ai</a></td></tr><tr><td>SiliconFlow</td><td>3</td><td>Sign-up</td><td>See overview <a href="/ultra_guides/en/free-cloud/#siliconflow">SiliconFlow</a></td><td><a href="https://cloud.siliconflow.cn/account/ak" target="_blank" rel="noreferrer">cloud.siliconflow.cn</a></td></tr><tr><td>xAI / Grok</td><td>3</td><td>Sign-up</td><td>Text (often credits)</td><td><a href="https://console.x.ai" target="_blank" rel="noreferrer">console.x.ai</a></td></tr><tr><td>DeepSeek</td><td>2</td><td>Sign-up</td><td>See overview <a href="/ultra_guides/en/free-cloud/#deepseek">DeepSeek</a></td><td><a href="https://platform.deepseek.com" target="_blank" rel="noreferrer">platform.deepseek.com</a></td></tr><tr><td>Others (Chutes, Glhf, AI21, Nscale, Nebius, etc.)</td><td>Few</td><td>Mostly sign-up</td><td>Follow freellm</td><td>See repo Quick Reference</td></tr></tbody></table><h3 id="renewable-free-quotas" tabindex="-1">Renewable free quotas <a class="header-anchor" href="#renewable-free-quotas" aria-label="Permalink to &quot;Renewable free quotas&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Provider</th><th>Notes</th><th>Handbook</th></tr></thead><tbody><tr><td>OpenRouter</td><td><code>:free</code> pool; ~$10+ top-up can raise free daily request caps</td><td><a href="/ultra_guides/en/free-cloud/openrouter">OpenRouter</a></td></tr></tbody></table><h2 id="quick-reference-·-base-url-and-app" tabindex="-1">Quick reference · Base URL and App <a class="header-anchor" href="#quick-reference-·-base-url-and-app" aria-label="Permalink to &quot;Quick reference · Base URL and App&quot;">​</a></h2><p>Most vendors work with <strong>Custom (OpenAI)</strong>. For Gemini use the App preset <strong>Gemini(Google)</strong> — do not force an OpenAI Base URL.</p><table tabindex="0"><thead><tr><th>Provider</th><th>Base URL (common)</th><th>App</th></tr></thead><tbody><tr><td>Groq</td><td><code>https://api.groq.com/openai/v1</code></td><td>Custom (OpenAI)</td></tr><tr><td>SiliconFlow</td><td><code>https://api.siliconflow.cn/v1</code></td><td>Custom (OpenAI)</td></tr><tr><td>Zhipu</td><td><code>https://open.bigmodel.cn/api/paas/v4</code></td><td>Custom (OpenAI)</td></tr><tr><td>Agnes AI</td><td><code>https://apihub.agnes-ai.com/v1</code></td><td>Custom (OpenAI)</td></tr><tr><td>OpenCode Zen</td><td><code>https://opencode.ai/zen/v1</code></td><td>Custom (OpenAI)</td></tr><tr><td>OpenRouter</td><td><code>https://openrouter.ai/api/v1</code></td><td><strong>OpenRouter</strong></td></tr><tr><td>NVIDIA NIM</td><td><code>https://integrate.api.nvidia.com/v1</code></td><td>Custom (OpenAI)</td></tr><tr><td>ModelScope</td><td><code>https://api-inference.modelscope.cn/v1</code></td><td>Custom (OpenAI)</td></tr><tr><td>GitHub Models</td><td><code>https://models.github.ai/inference</code></td><td>Custom (OpenAI)</td></tr><tr><td>Cerebras</td><td><code>https://api.cerebras.ai/v1</code></td><td>Custom (OpenAI)</td></tr><tr><td>SambaNova</td><td><code>https://api.sambanova.ai/v1</code></td><td>Custom (OpenAI)</td></tr><tr><td>Mistral</td><td><code>https://api.mistral.ai/v1</code></td><td>Custom (OpenAI)</td></tr><tr><td>Hugging Face</td><td><code>https://router.huggingface.co/v1</code></td><td>Custom (OpenAI)</td></tr><tr><td>LLM7.io</td><td><code>https://api.llm7.io/v1</code></td><td>Custom (OpenAI)</td></tr><tr><td>Ollama Cloud</td><td><code>https://api.ollama.com</code> (follow docs)</td><td>Custom (OpenAI)</td></tr><tr><td>Gemini</td><td>Preset</td><td><strong>Gemini(Google)</strong></td></tr><tr><td>DeepSeek</td><td>Preset</td><td><strong>DeepSeek</strong></td></tr><tr><td>Qwen / Bailian</td><td>Preset</td><td><strong>Qwen</strong></td></tr></tbody></table><p>Cloudflare Workers AI paths include <code>{account_id}</code> and are fiddly; if unsure, start with Groq / Zhipu / OpenRouter.</p><p>Full Key links and “best free model per vendor” tables: repo <a href="https://github.com/open-free-llm-api/awesome-freellm-apis/blob/main/README.zh-CN.md" target="_blank" rel="noreferrer">Best Free Models</a>.</p><h2 id="popular-free-models-repo-weekly-usage-examples" tabindex="-1">Popular free models (repo weekly usage examples) <a class="header-anchor" href="#popular-free-models-repo-weekly-usage-examples" aria-label="Permalink to &quot;Popular free models (repo weekly usage examples)&quot;">​</a></h2><p>Only “recently used” references — <strong>not</strong> necessarily best for roleplay:</p><table tabindex="0"><thead><tr><th>Direction</th><th>Examples (follow freellm / plaza IDs)</th></tr></thead><tbody><tr><td>Aggregated free pool</td><td>OpenRouter: <code>nvidia/nemotron-3-ultra-550b-a55b:free</code>, etc.</td></tr><tr><td>Fast inference</td><td>Groq: <code>llama-3.3-70b-versatile</code>, <code>moonshotai/kimi-k2-instruct</code></td></tr><tr><td>Chinese chat</td><td>Zhipu Flash, SiliconFlow free-tagged models, Bailian new-user quota</td></tr><tr><td>Multimodal text + image gen</td><td><a href="/ultra_guides/en/free-cloud/agnes-ai">Agnes AI</a>, <a href="/ultra_guides/en/free-cloud/aihubmix">AIHubMix</a></td></tr></tbody></table><h2 id="images-video" tabindex="-1">Images / video <a class="header-anchor" href="#images-video" aria-label="Permalink to &quot;Images / video&quot;">​</a></h2><ul><li>Many directory rows mark <code>image</code> / <code>video</code> modality; <strong>MiniTavern image gen</strong> needs OpenAI Images–compatible or App-supported platforms (see <a href="/ultra_guides/en/free-cloud/#free-image-generation">Free image gen</a>).</li><li>The App <strong>has no built-in video generation</strong>; video models are only for comparing site capabilities.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/ultra_guides/en/free-cloud/">Free cloud overview</a></li><li><a href="/ultra_guides/en/free-cloud/agnes-ai">Agnes AI</a> · <a href="/ultra_guides/en/free-cloud/opencode-zen">OpenCode Zen</a> · <a href="/ultra_guides/en/free-cloud/aihubmix">AIHubMix</a> · <a href="/ultra_guides/en/free-cloud/openrouter">OpenRouter</a></li><li><a href="/ultra_guides/en/manual/model-link">Model link</a></li><li><a href="/ultra_guides/en/manual/errors">Error codes</a></li></ul>',28)])])}const f=t(o,[["render",n]]);export{u as __pageData,f as default};
